import { pyRepr } from '../format/python_repr.mjs';

function basename(path) {
  if (!path) {
    return 'test11.mjs';
  }

  const normalized = path.replace(/\\/g, '/');
  const parts = normalized.split('/');
  return parts[parts.length - 1] || 'test11.mjs';
}

function usageLine(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

function helpText(programName) {
  return `${usageLine(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n`;
}

function errorText(programName, message) {
  return `${usageLine(programName)}\n${programName}: error: ${message}\n`;
}

function isOptionLike(token) {
  return token.length > 1 && token.startsWith('-');
}

function isIntLiteral(token) {
  return /^[+-]?\d+$/.test(token);
}

function parseIntLiteral(token) {
  return Number.parseInt(token, 10);
}

function helpResult(programName) {
  return {
    kind: 'help',
    code: 0,
    text: helpText(programName),
  };
}

function errorResult(programName, message) {
  return {
    kind: 'error',
    code: 2,
    text: errorText(programName, message),
  };
}

function missingArguments(values) {
  const missing = [];

  if (!Object.prototype.hasOwnProperty.call(values, 'a')) {
    missing.push('--a');
  }

  if (!Object.prototype.hasOwnProperty.call(values, 'b')) {
    missing.push('--b');
  }

  return missing;
}

export function parseTest11Args(argv, scriptPath) {
  const programName = basename(scriptPath);
  const values = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token === '-h' || token === '--help') {
      return helpResult(programName);
    }

    if (token.startsWith('--a=')) {
      values.a = token.slice(4);
      continue;
    }

    if (token === '--a') {
      const next = argv[index + 1];

      if (next === undefined || isOptionLike(next)) {
        return errorResult(programName, 'argument --a: expected one argument');
      }

      values.a = next;
      index += 1;
      continue;
    }

    if (token.startsWith('--b=')) {
      const value = token.slice(4);

      if (!isIntLiteral(value)) {
        return errorResult(
          programName,
          `argument --b: invalid int value: ${pyRepr(value)}`,
        );
      }

      values.b = parseIntLiteral(value);
      continue;
    }

    if (token === '--b') {
      const next = argv[index + 1];

      if (
        next === undefined ||
        (isOptionLike(next) && !isIntLiteral(next))
      ) {
        return errorResult(programName, 'argument --b: expected one argument');
      }

      if (!isIntLiteral(next)) {
        return errorResult(
          programName,
