function decodeEscape(char) {
  if (char === '\\' || char === "'" || char === '"') {
    return char;
  }

  if (char === 'n') {
    return '\n';
  }

  if (char === 'r') {
    return '\r';
  }

  if (char === 't') {
    return '\t';
  }

  return char;
}

function parseQuotedSegment(path, startIndex) {
  const quote = path[startIndex];
  let index = startIndex + 1;
  let value = '';

  while (index < path.length) {
    const char = path[index];

    if (char === '\\') {
      index += 1;

      if (index >= path.length) {
        throw new Error(`Invalid path: ${path}`);
      }

      value += decodeEscape(path[index]);
      index += 1;
      continue;
    }

    if (char === quote) {
      return {
        value,
        nextIndex: index + 1,
      };
    }

    value += char;
    index += 1;
  }

  throw new Error(`Invalid path: ${path}`);
}

function parseIndexSegment(path, startIndex) {
  let index = startIndex;

  while (index < path.length && path[index] !== ']') {
    index += 1;
  }

  if (index >= path.length) {
    throw new Error(`Invalid path: ${path}`);
  }

  const token = path.slice(startIndex, index);

  if (!/^\d+$/.test(token)) {
    throw new Error(`Invalid path: ${path}`);
  }

  return {
    value: Number.parseInt(token, 10),
    nextIndex: index,
  };
}

export function parsePath(path) {
  if (!path.startsWith('root')) {
    throw new Error(`Invalid path: ${path}`);
  }

  const segments = [];
  let index = 4;

  while (index < path.length) {
    if (path[index] !== '[') {
      throw new Error(`Invalid path: ${path}`);
    }

    index += 1;

    let parsed;
    const char = path[index];

    if (char === "'" || char === '"') {
      parsed = parseQuotedSegment(path, index);
    } else {
      parsed = parseIndexSegment(path, index);
    }

    index = parsed.nextIndex;

    if (path[index] !== ']') {
      throw new Error(`Invalid path: ${path}`);
    }

    segments.push(parsed.value);
    index += 1;
  }

  return segments;
}

export function extract(target, path) {
  const segments = parsePath(path);
  let current = target;

  for (const segment of segments) {
    if (current === null || current === undefined || !(segment in current)) {
      throw new Error(`Path not found: ${path}`);
    }

    current = current[segment];
  }

  return current;
}

