export function isPlainObject(value) {
  if (value === null || typeof value !== 'object') {
    return false;
  }

  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function chooseQuote(value) {
  if (!value.includes("'")) {
    return "'";
  }

  if (!value.includes('"')) {
    return '"';
  }

  return "'";
}

function escapeCodePoint(codePoint) {
  if (codePoint <= 0xff) {
    return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  }

  if (codePoint <= 0xffff) {
    return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  }

  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

export function quotePythonString(value) {
  const quote = chooseQuote(value);
  let escaped = '';

  for (const char of value) {
    const codePoint = char.codePointAt(0);

    if (char === '\\') {
      escaped += '\\\\';
      continue;
    }

    if (char === quote) {
      escaped += `\\${quote}`;
      continue;
    }

    if (char === '\n') {
      escaped += '\\n';
      continue;
    }

    if (char === '\r') {
      escaped += '\\r';
      continue;
    }

    if (char === '\t') {
      escaped += '\\t';
      continue;
    }

    if (codePoint < 0x20 || codePoint === 0x7f) {
      escaped += escapeCodePoint(codePoint);
      continue;
    }

    escaped += char;
  }

  return `${quote}${escaped}${quote}`;
}

export function pyRepr(value) {
  if (typeof value === 'string') {
    return quotePythonString(value);
  }

  if (typeof value === 'number') {
    if (Object.is(value, -0)) {
      return '0';
    }

    if (Number.isNaN(value)) {
      return 'nan';
    }

    if (value === Infinity) {
      return 'inf';
    }

    if (value === -Infinity) {
      return '-inf';
    }

    return String(value);
  }

  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }

  if (value === null || value === undefined) {
    return 'None';
  }

  if (Array.isArray(value)) {
    const items = value.map((item) => pyRepr(item));
    return `[${items.join(', ')}]`;
  }

  if (isPlainObject(value)) {
    const entries = Object.entries(value).map(
      ([key, item]) => `${pyRepr(key)}: ${pyRepr(item)}`,
    );
    return `{${entries.join(', ')}}`;
  }

  return quotePythonString(String(value));
}

export function formatForPrint(value) {
  return typeof value === 'string' ? value : pyRepr(value);
}

